#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_bf16_contiguous(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. The definition declares:
//   hidden_states: [batch_size, hidden_size]  bf16
//   weight       : [hidden_size]              bf16
//   output       : [batch_size, hidden_size]  bf16  (DPS, pre-alloc)
//
// hidden_size is constant at 128 per definition.json; EPS is pinned
// at 1e-6 in the kernel body (problem definition).
void run(
    const torch::Tensor& hidden_states,
    const torch::Tensor& weight,
    torch::Tensor output) {
    TORCH_CHECK(
        hidden_states.dim() == 2,
        "hidden_states must be 2D [batch, hidden]; got ",
        hidden_states.dim(), "D");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1D");

    const int64_t hidden_size = hidden_states.size(1);
    TORCH_CHECK(
        hidden_size == 128,
        "hidden_size must be 128 for problem_021, got ", hidden_size);
    TORCH_CHECK(
        weight.size(0) == hidden_size,
        "weight must have size ", hidden_size, ", got ", weight.size(0));

    check_bf16_contiguous(hidden_states, "hidden_states");
    check_bf16_contiguous(weight, "weight");
    check_bf16_contiguous(output, "output");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_021_rmsnorm_h128_launcher(
        hidden_states,
        weight,
        output,
        stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "RMSNorm at hidden_size=128; BF16 inputs / output, FP32 "
        "accumulator; EPS=1e-6 pinned by problem definition; "
        "destination-passing style.");
}

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// One CTA per row of [batch, hidden_size=128]. Threads cooperatively
// reduce sum-of-squares of hidden_states in FP32, then rescale
// hidden_states * inv_rms * weight and store BF16. No residual add —
// plain RMSNorm variant captured from Qwen3-30B-A3B at h=128.

namespace {

__device__ inline float warp_all_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_xor_sync(0xFFFFFFFFu, val, offset);
    }
    return val;
}

constexpr int HIDDEN_SIZE = 128;
constexpr int HIDDEN_SIZE_VEC = 64;     // BF16x2 pairs per row
constexpr int BLOCK_THREADS = 64;       // one BF16x2 pair per thread
constexpr int MAX_WARPS = 4;            // 64 threads = 2 warps; pad to 4
constexpr float EPS = 1e-6f;            // pinned by problem definition

__global__ void __launch_bounds__(BLOCK_THREADS, 8)
problem_021_rmsnorm_h128_kernel(
    const __nv_bfloat16* __restrict__ hidden_states,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int batch_size) {

    const int row = blockIdx.x;
    if (row >= batch_size) return;

    const __nv_bfloat162* hs_row =
        reinterpret_cast<const __nv_bfloat162*>(hidden_states)
        + row * HIDDEN_SIZE_VEC;
    const __nv_bfloat162* w_vec =
        reinterpret_cast<const __nv_bfloat162*>(weight);
    __nv_bfloat162* out_row =
        reinterpret_cast<__nv_bfloat162*>(output) + row * HIDDEN_SIZE_VEC;

    const int tid = threadIdx.x;

    float thread_sum_sq = 0.0f;
    // BLOCK_THREADS == HIDDEN_SIZE_VEC: one BF16x2 pair per thread.
    if (tid < HIDDEN_SIZE_VEC) {
        __nv_bfloat162 hv = __ldg(hs_row + tid);
        float2 h_f2 = __bfloat1622float2(hv);
        thread_sum_sq = h_f2.x * h_f2.x + h_f2.y * h_f2.y;
    }

    thread_sum_sq = warp_all_reduce_sum(thread_sum_sq);

    __shared__ float s_warp[MAX_WARPS];
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int num_warps = (BLOCK_THREADS + 31) >> 5;
    if (lane == 0) s_warp[warp] = thread_sum_sq;
    __syncthreads();

    if (warp == 0) {
        float partial = (lane < num_warps) ? s_warp[lane] : 0.0f;
        partial = warp_all_reduce_sum(partial);
        if (lane == 0) s_warp[0] = partial;
    }
    __syncthreads();
    const float row_sum = s_warp[0];

    const float inv_rms = rsqrtf(row_sum / static_cast<float>(HIDDEN_SIZE) + EPS);

    if (tid < HIDDEN_SIZE_VEC) {
        __nv_bfloat162 hv = __ldg(hs_row + tid);
        __nv_bfloat162 wv = __ldg(w_vec + tid);
        float2 h_f2 = __bfloat1622float2(hv);
        float2 w_f2 = __bfloat1622float2(wv);
        float y0 = h_f2.x * inv_rms * w_f2.x;
        float y1 = h_f2.y * inv_rms * w_f2.y;
        out_row[tid] = __float22bfloat162_rn(make_float2(y0, y1));
    }
}

}  // namespace

void problem_021_rmsnorm_h128_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& weight,
    torch::Tensor& output,
    cudaStream_t stream) {

    const auto batch_size = static_cast<int>(hidden_states.size(0));
    dim3 grid(batch_size);
    dim3 block(BLOCK_THREADS);

    problem_021_rmsnorm_h128_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(hidden_states.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        batch_size);
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the plain (non-fused) RMSNorm kernel at
// hidden_size=128. Inputs and outputs are BF16; intermediate
// accumulation runs in FP32 per the precision contract
// (CLAUDE.md Rule 8). Output is pre-allocated by the eval
// driver and written in-place (destination-passing style).
// EPS is a compile-time constant baked into the kernel
// (1e-6 per the problem definition).
void problem_021_rmsnorm_h128_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& weight,
    torch::Tensor& output,
    cudaStream_t stream);
